// Remove the empty placeholder produced by "Always Output Data".
const inputItems = $input
  .all()
  .filter((item) => {
    const event = item.json;

    const hasEventData =
      event?.id ||
      event?.summary ||
      event?.start;

    const isNotCancelled =
      event?.status !== 'cancelled';

    return hasEventData && isNotCancelled;
  });

// Change these values later if a client prefers another format.
const locale = 'en-US';

// Use the timezone configured in the n8n workflow settings.
// Fall back to UTC if no workflow timezone is available.
const timeZone = $now.zoneName || 'UTC';

function formatDate(dateValue) {
  if (!dateValue) return '';

  // Adding noon prevents all-day dates from shifting backward
  // because of timezone conversion.
  const safeDateValue = dateValue.includes('T')
    ? dateValue
    : `${dateValue}T12:00:00`;

  const date = new Date(safeDateValue);

  if (Number.isNaN(date.getTime())) {
    return dateValue;
  }

  return new Intl.DateTimeFormat(locale, {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    year: 'numeric',
    timeZone,
  }).format(date);
}

function formatTime(dateTimeValue) {
  if (!dateTimeValue) return '';

  const date = new Date(dateTimeValue);

  if (Number.isNaN(date.getTime())) {
    return '';
  }

  return new Intl.DateTimeFormat(locale, {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
    timeZone,
  }).format(date);
}

// Creates a machine-friendly 24-hour value such as "09:45".
// This is used only for sorting, not shown in the email.
function createSortTime(dateTimeValue, allDay) {
  if (allDay) return '00:00';
  if (!dateTimeValue) return '23:59';

  const date = new Date(dateTimeValue);

  if (Number.isNaN(date.getTime())) {
    return '23:59';
  }

  return new Intl.DateTimeFormat('en-GB', {
    hour: '2-digit',
    minute: '2-digit',
    hourCycle: 'h23',
    timeZone,
  }).format(date);
}

const events = inputItems.map((item) => {
  const event = item.json;

  const allDay = Boolean(event.start?.date);
  const rawDate = event.start?.date || event.start?.dateTime || '';

  const startTime = allDay
    ? ''
    : formatTime(event.start?.dateTime);

  const endTime = allDay
    ? ''
    : formatTime(event.end?.dateTime);

  const sortTime = createSortTime(
    event.start?.dateTime,
    allDay
  );

  let displayTime = 'Time not specified';

  if (allDay) {
    displayTime = 'All Day';
  } else if (startTime && endTime) {
    displayTime = `${startTime} – ${endTime}`;
  } else if (startTime) {
    displayTime = `Starts at ${startTime}`;
  }

  return {
    name: event.summary?.trim() || 'Untitled Event',
    date: formatDate(rawDate),
    rawDate,
    sortTime,
    startTime,
    endTime,
    displayTime,
    allDay,
    location: event.location?.trim() || '',
    description: event.description?.trim() || '',
    calendar:
      event.organizer?.displayName ||
      event.organizer?.email ||
      'Google Calendar',
    link: event.htmlLink || '',
    status: event.status || '',
    eventId: event.id || '',
  };
});

// Sort by date first, then time.
// All-day events use 00:00 and appear first.
// Events missing a time use 23:59 and appear last.
events.sort((a, b) => {
  const aDate = (a.rawDate || '').slice(0, 10);
  const bDate = (b.rawDate || '').slice(0, 10);

  const dateComparison = aDate.localeCompare(bDate);

  if (dateComparison !== 0) {
    return dateComparison;
  }

  return a.sortTime.localeCompare(b.sortTime);
});

return [
  {
    json: {
      eventCount: events.length,
      agendaDate: events[0]?.date || '',
      timeZone,
      events,
    },
  },
];

// =========================
// TEMPLATE SETTINGS
// =========================

const THEME = {
  title: "📅 Tomorrow's Schedule",

  primary: "#2563eb",
  success: "#16a34a",

  background: "#f3f4f6",
  card: "#ffffff",
  border: "#e5e7eb",

  titleColor: "#111827",
  textColor: "#374151",
  mutedColor: "#6b7280",

  font: "Arial, Helvetica, sans-serif",

  buttonText: "Open in Google Calendar",

  footer: "Powered by Google Calendar + n8n",
};

const data = $input.first().json;
const events = data.events ?? [];
const agendaDate = data.agendaDate || 'Tomorrow';

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

const eventCards = events.length > 0
  ? events.map((event) => {
      const location = event.location
        ? `<div style="margin-top:8px;color:${THEME.textColor};">📍 ${escapeHtml(event.location)}</div>`
        : '';

      const description = event.description
        ? `<div style="margin-top:8px;color:${THEME.textColor};">${escapeHtml(event.description)}</div>`
        : '';
    const timeBadge = event.startTime
  ? `
    <div style="
      display:inline-block;
      padding:6px 10px;
      border-radius:999px;
      background:#dbeafe;
      color:#1d4ed8;
      font-size:13px;
      font-weight:700;
      margin-bottom:10px;
    ">
      ${escapeHtml(event.displayTime)}
    </div>
  `
  : '';

      const calendarLink = event.link
        ? `
          <div style="
            margin-top:18px;
            text-align:center;
          ">
            <a
              href="${escapeHtml(event.link)}"
              style="
                display:inline-block;
                padding:10px 14px;
                background:${THEME.primary};
                color:#ffffff;
                text-decoration:none;
                font-size:14px;
                font-weight:700;
                border-radius:8px;
              "
            >
              ${escapeHtml(THEME.buttonText)}
            </a>
          </div>
        `
        : '';

      return `
  <div style="
    margin-bottom:24px;
    padding:18px;
    border:1px solid ${THEME.border};
    border-radius:12px;
    background:${THEME.card};
  ">
    ${timeBadge}

    <div style="
      font-size:18px;
      font-weight:700;
      color:${THEME.titleColor};
    ">
      ${escapeHtml(event.name)}
    </div>

    ${location}
    ${description}
    ${calendarLink}
  </div>
`;
    }).join('')
  : `
    <div style="
      padding:28px 20px;
      border:1px solid ${THEME.border};
      border-radius:12px;
      background:${THEME.card};
      text-align:center;
    ">
      <div style="
        font-size:18px;
        font-weight:700;
        color:${THEME.titleColor};
        margin-bottom:8px;
      ">
        No events scheduled
      </div>

      <div style="
        font-size:14px;
        color:${THEME.mutedColor};
      ">
        Your calendar is clear for tomorrow.
      </div>
    </div>
  `;

const subject = `${THEME.title.replace('📅 ', '')} - ${agendaDate}`;

const html = `
<!DOCTYPE html>
<html>
  <body style="
    margin:0;
    padding:0;
    background:${THEME.background};
    font-family:${THEME.font};
  ">
    <div style="
      max-width:600px;
      margin:0 auto;
      padding:32px 16px;
    ">
      <div style="
        background:${THEME.card};
        border-radius:16px;
        padding:28px;
        box-shadow:0 4px 14px rgba(0,0,0,0.06);
      ">
        <div style="
          font-size:26px;
          font-weight:700;
          color:${THEME.titleColor};
          margin-bottom:6px;
        ">
          ${escapeHtml(THEME.title)}
        </div>

        <div style="
  font-size:16px;
  color:${THEME.mutedColor};
  margin-bottom:6px;
">
  ${escapeHtml(agendaDate)}
</div>

<div style="
  font-size:14px;
  color:#9ca3af;
  margin-bottom:24px;
">
  ${events.length} ${events.length === 1 ? 'event' : 'events'} scheduled
</div>

        ${eventCards}

        <div style="
          margin-top:24px;
          padding-top:18px;
          border-top:1px solid ${THEME.border};
          font-size:13px;
          color:#9ca3af;
          text-align:center;
        ">
          ${escapeHtml(THEME.footer)}
        </div>
      </div>
    </div>
  </body>
</html>
`;

return [
  {
    json: {
      subject,
      html,
      eventCount: events.length,
    },
  },
];
